questions.question:
The catalog state after a first refactor:

type CatalogState = {
  isLoading: boolean;
  isError: boolean;
  errorMessage: string | null;
  courses: Course[];
};

const [state, setState] = useState<CatalogState>({
  isLoading: false, isError: false, errorMessage: null, courses: [],
});

// in the search handler
setState((s) => ({ ...s, isLoading: true }));

Statement: "Because every field has a precise type, TypeScript rejects a state in which isLoading and isError are both true, or isError is true while errorMessage is null."

After switching to a discriminated union, a teammate writes:

type CatalogUiState =
  | { kind: "loading" }
  | { kind: "error"; message: string; canRetry: boolean }
  | { kind: "empty"; query: string }
  | { kind: "success"; courses: Course[]; refreshing: boolean };

function CatalogBody({ state }: { state: CatalogUiState }) {
  if (state.kind === "error") return <ErrorPanel message={state.message} />;
  return <CourseGrid courses={state.courses} />;
}

$ npx tsc --noEmit
CatalogBody.tsx:9:43 - error TS2339: Property 'courses' does not exist on type 'CatalogUiState'.
  Property 'courses' does not exist on type '{ kind: "loading"; }'.

Statement: "The error points at a real bug: as written, the component would render CourseGrid while the catalog is still loading or has no results."
